You are an expert at analyzing E-rate RFP and Form 470 documents. Extract all equipment requirements including switches, wireless access points, routers, controllers, and any other networking equipment. Return a structured JSON object with the following format:
{
  "requirements": [
    {
      "category": "switches",
      "quantity": 10,
      "specifications": "24-port PoE+ Gigabit switches",
      "preferredManufacturer": "Ruckus or equivalent",
      "requiredFeatures": ["PoE+", "Layer 3", "10G uplinks"]
    }
  ],
  "budget": "$50,000",
  "deadline": "2025-11-15",
  "specialRequirements": [],
  "contactInfo": {}
}

parameters.jsCode:
// Parse AI response and structure the data
const aiResponse = $input.item.json.message.content;
let requirements;

try {
  // Extract JSON from markdown code blocks if present
  const jsonMatch = aiResponse.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (jsonMatch) {
    requirements = JSON.parse(jsonMatch[1]);
  } else {
    requirements = JSON.parse(aiResponse);
  }
} catch (error) {
  // Fallback if JSON parsing fails
  requirements = {
    requirements: [],
    rawText: aiResponse,
    parseError: error.message
  };
}

return [{
  json: {
    applicationNumber: $input.item.json.applicationNumber,
    applicantName: $input.item.json.applicantName,
    state: $input.item.json.state,
    pdfType: $input.item.json.currentPdf.type,
    extractedRequirements: requirements,
    processedAt: new Date().toISOString()
  }
}];

// Aggregate all PDF analyses for this application
const items = $input.all();
const firstItem = items[0].json;

// Combine requirements from all PDFs
const allRequirements = [];
const budgetInfo = [];
const deadlines = [];

items.forEach(item => {
  if (item.json.extractedRequirements.requirements) {
    allRequirements.push(...item.json.extractedRequirements.requirements);
  }
  if (item.json.extractedRequirements.budget) {
    budgetInfo.push(item.json.extractedRequirements.budget);
  }
  if (item.json.extractedRequirements.deadline) {
    deadlines.push(item.json.extractedRequirements.deadline);
  }
});

return [{
  json: {
    applicationNumber: firstItem.applicationNumber,
    applicantName: firstItem.applicantName,
    state: firstItem.state,
    requirements: allRequirements,
    budget: budgetInfo[0] || null,
    deadline: deadlines[0] || null,
    totalPDFsAnalyzed: items.length,
    readyForBOM: true
  }
}];
